#!/usr/bin/env python3
"""Regenerate docs/KPI_DICTIONARY.md and docs/DATA_QUALITY.md from published build outputs.

Run after a build so the documentation's numbers always match the data.
"""
from __future__ import annotations

import csv
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PUB = ROOT / "data" / "published"
DOCS = ROOT / "docs"


def read(name):
    with (PUB / name).open(newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def kpi_dictionary():
    lines = [
        "# KPI Dictionary",
        "",
        "Generated by `scripts/render_docs.py` from `data/published/metric_dictionary.csv`.",
        "",
        "| KPI | Domain | Unit | Class | Formula or source field | Source |",
        "|---|---|---|---|---|---|",
    ]
    for r in read("metric_dictionary.csv"):
        formula = r["formula"] if r["formula"] != "SEC XBRL reported value" else r["source_field"]
        lines.append(f"| `{r['metric_id']}` {r['metric_name']} | {r['domain']} | {r['unit']} | {r['metric_type']} "
                     f"| {formula} | {r['source_system']} |")
    lines += [
        "",
        "## Classes",
        "",
        "- **Reported**: present in an official source field (SEC filing, T-100, Form 41).",
        "- **Derived**: calculated only from reported values with the formula shown. SEC quarters obtained as",
        "  full year minus nine months, or as a year-to-date difference, are stored as reported metrics with",
        "  the method recorded in `fact_financial_actual.method`.",
        "- **Modeled**: depends on the analyst FP&A model (budget, forecast, scenarios). Not company guidance.",
        "",
    ]
    (DOCS / "KPI_DICTIONARY.md").write_text("\n".join(lines), encoding="utf-8")


def data_quality():
    qa = json.loads((PUB / "qa_summary.json").read_text(encoding="utf-8"))
    val = json.loads((PUB / "validation_report.json").read_text(encoding="utf-8"))
    passed = sum(c["pass"] for c in val["checks"].values())
    lines = [
        "# Data Quality Report",
        "",
        "Generated by `scripts/render_docs.py` from `data/published/validation_report.json` and `qa_summary.json`.",
        "",
        f"**Status: {val['status']}**. {passed} of {len(val['checks'])} checks passed. Build {qa['build_timestamp_utc']}.",
        "",
        "| Check | Result | Detail |",
        "|---|---|---|",
    ]
    for name, c in val["checks"].items():
        lines.append(f"| `{name}` | {'Pass' if c['pass'] else 'Fail'} | {c['detail']} |")
    f, n, a, f41 = qa["financial"], qa["network"], qa["airports"], qa["form41"]
    lines += [
        "",
        "## Coverage",
        "",
        "| Item | Value |",
        "|---|---|",
        f"| SEC source | {f['source']} |",
        f"| SEC latest quarter end | {f['latest_quarter_end']} |",
        f"| Largest gap between four quarters and the reported full year | ${f['fy_reconciliation_max_abs_difference']:,.0f} |",
        f"| T-100 months | {n['period_min'][:7]} to {n['period_max'][:7]} |",
        f"| T-100 aircraft-detail rows | {n['aircraft_detail_rows']:,} |",
        f"| T-100 route-month rows | {n['route_month_rows']:,} |",
        f"| Directional routes | {n['directional_routes']:,} |",
        f"| Latest twelve-month window | {n['ttm_start'][:7]} to {n['ttm_end'][:7]} |",
        f"| Airports observed / with coordinates | {a['observed']} / {a['with_coordinates']} |",
        f"| Airports still without coordinates | {', '.join(a['pending_codes']) or 'none'} |",
        f"| Share of TTM passengers on mapped routes | {a['ttm_passenger_share_on_mapped_routes']:.2%} |",
        f"| Form 41 P-1.2 regions | {', '.join(f41['regions_seen'])} |",
        f"| Form 41 revenue / SEC revenue | {f41['revenue_ratio_to_sec_min']:.4f} to {f41['revenue_ratio_to_sec_max']:.4f} |",
        f"| Unit-economics quarters | {qa['unit_economics']['quarters'][0]} to {qa['unit_economics']['quarters'][-1]} |",
        "",
        "## SEC values by method (quarters and full years)",
        "",
        "| Metric | " + " | ".join(["reported", "derived_fy_minus_9m", "derived_ytd_difference",
                                     "derived_sum_of_components"]) + " |",
        "|---|---|---|---|---|",
    ]
    for metric, methods in f["methods"].items():
        lines.append(f"| `{metric}` | " + " | ".join(str(methods.get(m, 0)) for m in
                     ["reported", "derived_fy_minus_9m", "derived_ytd_difference", "derived_sum_of_components"]) + " |")
    lines += ["", "## Scope", "", qa["scope_note"], "", qa["scenario_integrity_note"], ""]
    (DOCS / "DATA_QUALITY.md").write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    kpi_dictionary()
    data_quality()
    print("Wrote docs/KPI_DICTIONARY.md and docs/DATA_QUALITY.md")
